USE PK_Ops;
GO

CREATE TABLE mrp_part_class_mode (
	part_class VARCHAR(32) NOT NULL, 
	mode VARCHAR(8) NOT NULL, 
	updated_at DATETIME NOT NULL, 
	updated_by VARCHAR(128) NOT NULL, 
	PRIMARY KEY (part_class)
);

CREATE TABLE mrp_run (
	run_id INTEGER NOT NULL IDENTITY, 
	plan_date DATE NOT NULL, 
	started_at DATETIME NOT NULL, 
	finished_at DATETIME NULL, 
	host VARCHAR(64) NULL, 
	app_version VARCHAR(32) NULL, 
	inputs_hash VARCHAR(64) NOT NULL, 
	inputs_json NVARCHAR(max) NULL, 
	status VARCHAR(16) NOT NULL, 
	PRIMARY KEY (run_id)
);

CREATE INDEX ix_mrp_run_plan_date ON mrp_run (plan_date);

CREATE TABLE mrp_segment_history (
	id INTEGER NOT NULL IDENTITY, 
	effective_date DATE NOT NULL, 
	part VARCHAR(32) NOT NULL, 
	segment VARCHAR(16) NOT NULL, 
	p50_days INTEGER NULL, 
	p80_days INTEGER NULL, 
	reasons NVARCHAR(max) NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_mrp_segment_day_part UNIQUE (effective_date, part)
);

CREATE TABLE mrp_settings (
	setting_key VARCHAR(64) NOT NULL, 
	setting_value NVARCHAR(max) NULL, 
	updated_at DATETIME NOT NULL, 
	updated_by VARCHAR(128) NOT NULL, 
	PRIMARY KEY (setting_key)
);

CREATE TABLE mrp_recommendation (
	rec_id INTEGER NOT NULL IDENTITY, 
	run_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	kind VARCHAR(24) NOT NULL, 
	part VARCHAR(32) NOT NULL, 
	ref VARCHAR(48) NULL, 
	qty FLOAT NULL, 
	need_by DATE NULL, 
	place_by DATE NULL, 
	lead_days FLOAT NULL, 
	lead_source VARCHAR(48) NULL, 
	segment VARCHAR(16) NULL, 
	mode VARCHAR(8) NOT NULL, 
	order_count INTEGER NULL, 
	order_value FLOAT NULL, 
	why_json NVARCHAR(max) NULL, 
	content_hash VARCHAR(64) NOT NULL, 
	closed_run_id INTEGER NULL, 
	closed_at DATETIME NULL, 
	closed_reason VARCHAR(64) NULL, 
	PRIMARY KEY (rec_id), 
	FOREIGN KEY(run_id) REFERENCES mrp_run (run_id), 
	FOREIGN KEY(closed_run_id) REFERENCES mrp_run (run_id)
);

CREATE INDEX ix_mrp_rec_open ON mrp_recommendation (content_hash, closed_run_id);

CREATE INDEX ix_mrp_rec_part ON mrp_recommendation (part, kind);

CREATE TABLE mrp_outcome (
	outcome_id INTEGER NOT NULL IDENTITY, 
	rec_id INTEGER NULL, 
	observed_at DATETIME NOT NULL, 
	what VARCHAR(24) NOT NULL, 
	part VARCHAR(32) NOT NULL, 
	ref VARCHAR(48) NULL, 
	qty FLOAT NULL, 
	event_date DATE NULL, 
	detail NVARCHAR(max) NULL, 
	PRIMARY KEY (outcome_id), 
	FOREIGN KEY(rec_id) REFERENCES mrp_recommendation (rec_id)
);

CREATE INDEX ix_mrp_outcome_part ON mrp_outcome (part, event_date);

CREATE INDEX ix_mrp_outcome_rec ON mrp_outcome (rec_id);

